use std::collections::HashSet;impl Solution{pub fn find_words(mut b:Vec<Vec<char>>,words:Vec<String>)->Vec<String>{let dict:HashSet<String>=words.into_iter().collect();let max=dict.iter().map(|s|s.len()).max().unwrap_or(0);let mut found=HashSet::new();fn f(b:&mut Vec<Vec<char>>,i:i32,j:i32,s:&mut String,d:&HashSet<String>,max:usize,o:&mut HashSet<String>){if i<0||j<0||i>=b.len()as i32||j>=b[0].len()as i32||b[i as usize][j as usize]=='#'||s.len()>=max{return}let c=b[i as usize][j as usize];s.push(c);if d.contains(s){o.insert(s.clone());}b[i as usize][j as usize]='#';f(b,i+1,j,s,d,max,o);f(b,i-1,j,s,d,max,o);f(b,i,j+1,s,d,max,o);f(b,i,j-1,s,d,max,o);b[i as usize][j as usize]=c;s.pop();}for i in 0..b.len(){for j in 0..b[0].len(){f(&mut b,i as i32,j as i32,&mut String::new(),&dict,max,&mut found);}}found.into_iter().collect()}}
